def main():
    assert set(P.keys()) == set(BATCH_IDS), f"prediction keys mismatch: {sorted(set(P.keys()) ^ set(BATCH_IDS))}"
    PRED_DIR.mkdir(parents=True, exist_ok=True)
    for cid in BATCH_IDS:
        rec = P[cid]
        out = {"case_id": cid, "prediction_text": rec["prediction_text"], "basis": rec["basis"],
               "confidence": rec["confidence"], "trigger": rec["trigger"]}
        assert 0.0 <= out["confidence"] <= 1.0
        assert set(out["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        assert all(isinstance(out["trigger"][k], bool) for k in ("changed_main", "reserve_used", "disputed"))
        (PRED_DIR / f"{cid}.json").write_text(json.dumps(out, ensure_ascii=False, indent=2), encoding="utf-8")
    # re-read validation
    written = 0
    counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    for cid in BATCH_IDS:
        data = json.loads((PRED_DIR / f"{cid}.json").read_text(encoding="utf-8"))
        assert data["case_id"] == cid, f"case_id mismatch {cid}"
        for f in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
            assert f in data and data[f] not in (None, ""), f"missing field {f} in {cid}"
        for k in counts:
            counts[k] += 1 if data["trigger"][k] else 0
        written += 1
    assert written == len(BATCH_IDS) == 20
    print(json.dumps({"batch_cases": len(BATCH_IDS), "written": written, "trigger_counts": counts}, ensure_ascii=False))

if __name__ == "__main__":
    main()
